INSERT INTO tp_exams (exam_code, kind, title, subtitle, description, difficulty, time_limit_sec, status, created_by) VALUES
('TP-PRACTICE-2026-SET03','PRACTICE','TOEFL iBT Practice — Set 03 (Full-Length 2026 Format)','Reading 50 · Listening 47 · Writing 12 · Speaking 11','A full-length practice set laid out like the 2026 TOEFL iBT: Reading opens with word completion and everyday texts before academic passages, Listening moves from short responses through conversations, announcements and talks, then Writing and Speaking close the session in ninety minutes. Every passage, dialogue and option here was composed for TestPrep rather than taken from released test material, so the structure is familiar while the content is entirely new. Auto-scored items are reported as a TestPrep internal band estimate, not an official ETS score.',NULL,5400,'PUBLISHED','admin');
